// @brief 初始化，启动设备
static int32_t acc_simulate_init(uint8_t* p_chip_id)
{
    if (p_chip_id) {
        *p_chip_id = 0x10;
    }
    return ERROR_CODE_SUCCESS;
}

// @brief 去初始化，设备处于低功耗状态
static void acc_simulate_uninit(bool is_power_off)
{
    print_warning("uninit. is_power_off=%d", is_power_off);
}

// @brief 模拟读取数据
static uint8_t acc_fifo_data_read(gsensor_val_t* p_data, uint8_t count)
{
    static uint32_t prev_ms = 0;
    static uint32_t offset = 0;
    static uint32_t start_ms = 0;
    static bool silent_flag = false;
    const gsensor_val_t* p_gsensor;
    uint32_t gsensor_count;
    uint32_t now_ms;
    uint32_t timeout_ms, diff_ms;
    uint8_t read_cnt;
    
    now_ms = htd_time_ms_get();
    if (silent_flag) {
        timeout_ms = 300*1000;
        p_gsensor = gsensor_simulator_data1;
        gsensor_count = ARRAY_COUNT(gsensor_simulator_data1);
    } else {
        timeout_ms = 120*1000;
        p_gsensor = gsensor_simulator_data2;
        gsensor_count = ARRAY_COUNT(gsensor_simulator_data2);
    }
    if (htd_time_ms_diff(now_ms, start_ms) > timeout_ms) {
        offset = 0;
        start_ms = now_ms;
        silent_flag = !silent_flag;
    }
    
    if (prev_ms == 0) {
        prev_ms = now_ms;
        read_cnt = 8;
    } else {
        diff_ms = htd_time_ms_diff(now_ms, prev_ms);
        prev_ms = now_ms;
        read_cnt = (HTD_GSENSOR_SAMPLE_FREQ * diff_ms) / 1000;
    }
    count = MIN(count, read_cnt);
    read_cnt = count;
    while (count--) {
        *p_data++ = p_gsensor[offset++];
        if (offset >= gsensor_count) {
            offset = 0;
        }
    }
    return read_cnt;
}

// @brief 控制句柄
int32_t acc_simulate_ctrl(htd_gsensor_cmd_t cmd, void* p_param, uint32_t param_len)
{
    if (cmd == HTD_GSENSOR_CMD_FIFO_DATA_READ) {
        uint8_t count = param_len / sizeof(gsensor_val_t);
        count = acc_fifo_data_read((gsensor_val_t*)p_param, count);
        return count * sizeof(gsensor_val_t);
    }
    return 0;
}

// @brief 注册到上层应用中
static int32_t acc_simulate_register(void)
{
    const static htd_gsensor_dev_t mems_dev = {
        .chip_name = "simulate",
        .fifo_max_size = 32,
        .init = acc_simulate_init,
        .uninit = acc_simulate_uninit,
        .ctrl_handle = acc_simulate_ctrl,
    };
    return htd_gsensor_dev_register(&mems_dev);
}
DEVICE_INIT_FUNC_REGISTER(acc_simulate_register);
#endif /*(defined(HTD_GSENSOR_USING_SIMULATE) && (HTD_GSENSOR_USING_SIMULATE == 1))*/

